try:
    result.pop('header', None)
    d = result.get('data')
    if not isinstance(d, dict):
        d = {}
        result['data'] = d
    v = str(d.get('verified')).lower()
    if str(d.get('all_verified')).lower() == 'true':
        w = 'Both answers are verified.'
    elif d.get('hint') == 'day_month_swapped':
        w = 'Day and month look swapped. Ask the customer to say the month as a word. This is not a wrong answer.'
    elif d.get('wrong_answers_left') == 0:
        w = 'Three wrong answers: the check failed. Do not state the debt. Tell the customer to use the mobile app or a branch, thank them and say goodbye.'
    elif v == 'true':
        w = 'Correct. Now ask for the last four digits of the phone number on file.'
    elif v == 'false':
        w = 'Wrong answer. Ask the same question again.'
    else:
        w = 'The answer was not checked. Ask for it again.'
    d['what_to_do_next'] = w
except Exception:
    pass

